import tkinter as tk
from tkinter import font
import cv2
from PIL import Image, ImageTk, ImageEnhance
import numpy as np
import os
from datetime import datetime
import base64, io

# ============================================================
# SNAPBOX — FLORAL RETRO EDITION
# Run: python3 interface_test.py
# ============================================================

W, H = 1000, 800
BG = "#F8E8D8"
PINK = "#D989A6"
DEEP_PINK = "#A95778"
DARK = "#251D22"
CREAM = "#FFF7F2"
SOFT = "#EEC6D2"
MUTED = "#856D76"

# The uploaded reference is embedded so the interface works from one Python file.
REFERENCE_BG = ""

root = tk.Tk()
root.title("SnapBox")
root.geometry(f"{W}x{H}")
root.resizable(False, False)
root.configure(bg=BG)
canvas = tk.Canvas(root, width=W, height=H, bg=BG, highlightthickness=0)
canvas.pack()

FAMILIES = set(font.families(root))
def pick_font(names, fallback="Helvetica"):
    for name in names:
        if name in FAMILIES:
            return name
    return fallback

DISPLAY = pick_font(["Bodoni 72", "Didot", "Bodoni MT", "Times New Roman"])
SANS = pick_font(["Avenir Next", "Helvetica Neue", "Helvetica"])

FILTERS = ["ORIGINAL", "VINTAGE", "B&W", "CREAM", "COOL", "FADED", "NOIR"]
FRAMES = ["NONE", "CLASSIC", "FILM", "SOFT", "POLAROID", "PEARL", "RIBBON"]
COLLAGES = [2, 3, 4, 5, 8]

PHOTO_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "photos")
os.makedirs(PHOTO_DIR, exist_ok=True)

# macOS camera: prefer AVFoundation, with a normal OpenCV fallback.
def open_camera():
    camera = cv2.VideoCapture(0, cv2.CAP_AVFOUNDATION)
    if not camera.isOpened():
        camera.release()
        camera = cv2.VideoCapture(0)
    camera.set(cv2.CAP_PROP_FRAME_WIDTH, 1280)
    camera.set(cv2.CAP_PROP_FRAME_HEIGHT, 720)
    return camera

cap = open_camera()

mode = "CAMERA"
panel = None
current_filter = "ORIGINAL"
current_frame = "NONE"
collage_target = 1
collage_frames = []
busy = False
count_job = None
camera_photo = None
review_photo = None
background_photo = None
camera_item = None

# Camera window inside the reference interface.
CAM_X, CAM_Y, CAM_W, CAM_H = 86, 398, 409, 306

# ------------------------------------------------------------
# Helpers
# ------------------------------------------------------------
def text(x, y, value, size=10, fill=DARK, family=None, anchor="center", weight="normal"):
    f = font.Font(family=family or SANS, size=size, weight=weight)
    return canvas.create_text(x, y, text=value, fill=fill, font=f, anchor=anchor)


def rounded_box(x1, y1, x2, y2, r=12, fill=CREAM, outline=""):
    pts = [x1+r,y1, x2-r,y1, x2,y1+r, x2,y2-r,
           x2-r,y2, x1+r,y2, x1,y2-r, x1,y1+r]
    return canvas.create_polygon(pts, smooth=True, fill=fill, outline=outline)


def load_background():
    global background_photo
    raw = base64.b64decode(REFERENCE_BG)
    img = Image.open(io.BytesIO(raw)).convert("RGB")
    background_photo = ImageTk.PhotoImage(img.resize((W, H), Image.Resampling.LANCZOS))


def draw_background():
    global camera_item
    canvas.delete("all")
    camera_item = None
    canvas.create_image(0, 0, image=background_photo, anchor="nw")


def fit_cv(frame, w, h):
    fh, fw = frame.shape[:2]
    ratio = max(w / fw, h / fh)
    nw, nh = int(fw * ratio), int(fh * ratio)
    resized = cv2.resize(frame, (nw, nh), interpolation=cv2.INTER_AREA)
    x = max(0, (nw - w) // 2)
    y = max(0, (nh - h) // 2)
    return resized[y:y+h, x:x+w].copy()


def apply_filter(img, name):
    if img is None:
        return None
    out = img.copy()
    if name == "ORIGINAL":
        return out
    if name == "B&W":
        g = cv2.cvtColor(out, cv2.COLOR_BGR2GRAY)
        return cv2.cvtColor(g, cv2.COLOR_GRAY2BGR)
    if name == "VINTAGE":
        b, g, r = cv2.split(out.astype(np.float32))
        arr = np.dstack([b*.88, g*.98, r*1.06]).clip(0,255).astype(np.uint8)
        pil = Image.fromarray(cv2.cvtColor(arr, cv2.COLOR_BGR2RGB))
        pil = ImageEnhance.Contrast(pil).enhance(.93)
        pil = ImageEnhance.Color(pil).enhance(.72)
        return cv2.cvtColor(np.array(pil), cv2.COLOR_RGB2BGR)
    if name == "CREAM":
        out = cv2.convertScaleAbs(out, alpha=.90, beta=16)
        b, g, r = cv2.split(out)
        r = np.clip(r*1.04, 0, 255).astype(np.uint8)
        return cv2.merge([b, g, r])
    if name == "COOL":
        b, g, r = cv2.split(out.astype(np.float32))
        return np.dstack([b*1.07, g, r*.93]).clip(0,255).astype(np.uint8)
    if name == "FADED":
        return cv2.convertScaleAbs(out, alpha=.82, beta=18)
    if name == "NOIR":
        g = cv2.cvtColor(out, cv2.COLOR_BGR2GRAY)
        g = cv2.convertScaleAbs(g, alpha=1.45, beta=-28)
        return cv2.cvtColor(g, cv2.COLOR_GRAY2BGR)
    return out


def vignette(img, strength=.08):
    h, w = img.shape[:2]
    Y, X = np.ogrid[:h, :w]
    dx = (X-w/2)/(w/2)
    dy = (Y-h/2)/(h/2)
    mask = 1-strength*np.clip((dx*dx+dy*dy)/2, 0, 1)
    return np.clip(img*mask[...,None], 0, 255).astype(np.uint8)

# ------------------------------------------------------------
# Frames — ribbon/flowers only live here.
# ------------------------------------------------------------
def add_frame_cv(img, name):
    out = img.copy()
    h, w = out.shape[:2]

    if name == "CLASSIC":
        cv2.rectangle(out, (8,8), (w-9,h-9), (248,244,240), 9)
    elif name == "FILM":
        cv2.rectangle(out, (8,8), (w-9,h-9), (25,25,25), 11)
        for yy in range(18, h-12, 34):
            cv2.rectangle(out, (12,yy), (28,yy+17), (238,238,238), -1)
            cv2.rectangle(out, (w-29,yy), (w-13,yy+17), (238,238,238), -1)
    elif name == "SOFT":
        cv2.rectangle(out, (9,9), (w-10,h-10), (226,188,199), 15)
    elif name == "POLAROID":
        cv2.rectangle(out, (10,10), (w-11,h-11), (255,255,255), 20)
        cv2.putText(out, "SNAPBOX", (w-150,h-24), cv2.FONT_HERSHEY_SIMPLEX, .55, (105,95,100), 1, cv2.LINE_AA)
    elif name == "PEARL":
        cv2.rectangle(out, (8,8), (w-9,h-9), (215,201,204), 9)
    elif name == "RIBBON":
        # Elegant pink corner ribbons + small flowers.
        cv2.rectangle(out, (9,9), (w-10,h-10), (62,33,45), 6)
        pink = (190,105,135)
        light = (235,160,184)
        yellow = (245,205,105)
        for cx, cy in [(62,62), (w-62,h-62)]:
            cv2.ellipse(out,(cx-25,cy-9),(cx,cy+11),18,0,360,pink,-1)
            cv2.ellipse(out,(cx,cy-9),(cx+25,cy+11),-18,0,360,pink,-1)
            cv2.circle(out,(cx,cy),10,light,-1)
            cv2.fillPoly(out,[np.array([[cx-7,cy+6],[cx-31,cy+33],[cx-8,cy+19]],np.int32)],pink)
            cv2.fillPoly(out,[np.array([[cx+7,cy+6],[cx+31,cy+33],[cx+8,cy+19]],np.int32)],pink)
        for cx, cy in [(84,h-58),(w-84,58)]:
            for ang in range(0,360,72):
                rad=np.deg2rad(ang)
                px=int(cx+12*np.cos(rad)); py=int(cy+12*np.sin(rad))
                cv2.circle(out,(px,py),7,(228,160,181),-1)
            cv2.circle(out,(cx,cy),6,yellow,-1)
    return out

# ------------------------------------------------------------
# Camera and collage
# ------------------------------------------------------------
def show_camera_frame(frame):
    """Update one persistent Canvas image item for a smooth live preview."""
    global camera_photo, camera_item
    fitted = fit_cv(frame, CAM_W, CAM_H)
    rgb = cv2.cvtColor(fitted, cv2.COLOR_BGR2RGB)
    camera_photo = ImageTk.PhotoImage(Image.fromarray(rgb))

    if camera_item is None or not canvas.find_withtag(camera_item):
        camera_item = canvas.create_image(
            CAM_X, CAM_Y, image=camera_photo, anchor="nw", tags="CAMERA_IMAGE"
        )
    else:
        canvas.itemconfig(camera_item, image=camera_photo)

    # The video must always sit above the reference artwork.
    canvas.tag_raise(camera_item)
    if canvas.find_withtag("CAMERA_BORDER"):
        canvas.tag_raise("CAMERA_BORDER")


def make_collage():
    imgs = list(collage_frames)
    if not imgs:
        return None
    if len(imgs) == 1:
        return imgs[0].copy()

    # Clean scrapbook-like layouts.
    if collage_target == 2:
        cols, rows = 2, 1
    elif collage_target == 3:
        cols, rows = 3, 1
    elif collage_target == 4:
        cols, rows = 2, 2
    elif collage_target == 5:
        cols, rows = 3, 2
    else:
        cols, rows = 4, 2

    cellw, cellh = 430, 300
    gap, pad = 18, 22
    out = np.full((rows*cellh+(rows+1)*gap, cols*cellw+(cols+1)*gap, 3), (248,232,216), np.uint8)
    for i, img in enumerate(imgs):
        thumb = fit_cv(img, cellw, cellh)
        r, c = divmod(i, cols)
        yy = gap + r*(cellh+gap)
        xx = gap + c*(cellw+gap)
        out[yy:yy+cellh, xx:xx+cellw] = thumb
        cv2.rectangle(out, (xx,yy), (xx+cellw-1,yy+cellh-1), (255,248,244), 5)
    return out

# ------------------------------------------------------------
# UI
# ------------------------------------------------------------
def bottom_button(x, y, w, title, active=True):
    fill = DARK if active else "#E9D6D2"
    fg = "#FFFFFF" if active else "#9C858C"
    rounded_box(x, y, x+w, y+40, 12, fill)
    text(x+w/2, y+20, title, 9, fg, SANS, weight="bold")


def camera_ui():
    draw_background()

    # Cover only the white camera screen from the reference with the live feed.
    # Everything else remains the floral retro interface.
    canvas.create_rectangle(CAM_X-3, CAM_Y-3, CAM_X+CAM_W+3, CAM_Y+CAM_H+3,
                            outline="#241D22", width=6, tags="CAMERA_BORDER")

    # Minimal title and status.
    text(500, 35, "SNAPBOX", 23, DARK, DISPLAY, weight="bold")
    text(500, 63, "RETRO PHOTO BOOTH", 8, MUTED, SANS, weight="bold")

    if collage_target > 1 and len(collage_frames) < collage_target:
        text(500, 760, f"COLLAGE  •  PHOTO {len(collage_frames)+1} / {collage_target}", 9, DARK, SANS, weight="bold")
    else:
        text(500, 760, "READY", 9, DARK, SANS, weight="bold")

    # Bottom controls sit over the cream area, not over the camera.
    bottom_button(95, 705, 120, "FILTERS", False)
    bottom_button(230, 705, 120, "FRAMES", False)
    bottom_button(365, 705, 120, "COLLAGE", True)

    canvas.create_oval(505, 700, 595, 790, fill=CREAM, outline=DARK, width=3)
    canvas.create_oval(518, 713, 582, 777, fill=PINK, outline=DARK, width=2)
    text(550, 748, "●", 15, DARK, SANS)
    text(550, 687, "SHUTTER", 8, MUTED, SANS, weight="bold")

    if panel == "COLLAGE":
        collage_popup()


def collage_popup():
    # Compact menu in the lower-right cream area.
    x1,y1,x2,y2 = 650, 565, 965, 700
    rounded_box(x1,y1,x2,y2,16,CREAM,outline=PINK)
    text(808, 588, "CHOOSE COLLAGE", 10, DARK, SANS, weight="bold")
    xs = [670, 815]
    for i,n in enumerate(COLLAGES):
        row=i//2; col=i%2
        x=xs[col]; y=607+row*34
        w=125
        rounded_box(x,y,x+w,y+27,9,DARK)
        text(x+w/2,y+13.5,f"{n} PHOTOS",8,"#FFFFFF",SANS,weight="bold")


def review_ui():
    global review_photo
    draw_background()

    # Soft review card over the lower cream section.
    rounded_box(110, 360, 890, 700, 22, CREAM, outline=PINK)
    base = make_collage()
    if base is not None:
        base = apply_filter(base, current_filter)
        base = vignette(base, .08)
        base = add_frame_cv(base, current_frame)
        rgb = cv2.cvtColor(base, cv2.COLOR_BGR2RGB)
        pil = Image.fromarray(rgb)
        ratio = min(680/pil.width, 285/pil.height)
        pil = pil.resize((int(pil.width*ratio), int(pil.height*ratio)), Image.Resampling.LANCZOS)
        review_photo = ImageTk.PhotoImage(pil)
        canvas.create_image(500, 515, image=review_photo, anchor="center", tags="REVIEW_IMAGE")

    # Controls.
    rounded_box(110, 65, 890, 330, 22, CREAM, outline=PINK)
    text(500, 92, "YOUR PHOTO", 15, DARK, DISPLAY, weight="bold")
    text(500, 118, "Choose a simple filter or frame", 8, MUTED, SANS)
    bottom_button(160, 145, 150, "FILTERS", panel == "FILTERS")
    bottom_button(325, 145, 150, "FRAMES", panel == "FRAMES")
    bottom_button(490, 145, 150, "RETAKE", True)
    bottom_button(655, 145, 150, "SAVE PHOTO", True)

    if panel == "FILTERS":
        option_panel(160, 205, FILTERS, current_filter)
    elif panel == "FRAMES":
        option_panel(160, 205, FRAMES, current_frame)
    else:
        text(500, 225, f"{collage_target} PHOTO COLLAGE" if collage_target > 1 else "SINGLE PHOTO", 11, DARK, SANS, weight="bold")
        text(500, 248, "Your selected look will be shown below.", 8, MUTED, SANS)


def option_panel(x, y, items, selected):
    # Simple, clean options — no dots or extra decoration.
    for i,item in enumerate(items):
        col=i%4; row=i//4
        xx=x+col*165; yy=y+row*38
        active=item==selected
        rounded_box(xx,yy,xx+150,yy+30,9,PINK if active else DARK)
        text(xx+75,yy+15,item,8,"#FFFFFF",SANS,weight="bold")

# ------------------------------------------------------------
# Countdown / capture
# ------------------------------------------------------------
def camera_flash():
    canvas.delete("FLASH")
    canvas.create_rectangle(CAM_X, CAM_Y, CAM_X+CAM_W, CAM_Y+CAM_H,
                            fill="#FFFFFF", outline="", tags="FLASH")
    canvas.tag_raise("FLASH")
    root.after(120, lambda: canvas.delete("FLASH"))


def countdown(n):
    global count_job
    if not busy:
        return
    canvas.delete("COUNT")
    f = font.Font(family=DISPLAY, size=82)
    canvas.create_text(CAM_X+CAM_W/2, CAM_Y+CAM_H/2, text=str(n), fill="#FFFFFF", font=f, tags="COUNT")
    canvas.tag_raise("COUNT")
    if n > 1:
        count_job = root.after(700, lambda: countdown(n-1))
    else:
        count_job = root.after(700, capture_photo)


def start_countdown():
    canvas.delete("COUNT")
    f = font.Font(family=DISPLAY, size=25)
    canvas.create_text(CAM_X+CAM_W/2, CAM_Y+CAM_H/2, text="GET READY", fill="#FFFFFF", font=f, tags="COUNT")
    canvas.tag_raise("COUNT")
    root.after(600, lambda: countdown(3))


def take_photo(event=None):
    global busy
    if mode != "CAMERA" or busy:
        return
    busy = True
    start_countdown()


def capture_photo():
    global busy, mode, panel
    canvas.delete("COUNT")
    ret, frame = cap.read()
    if not ret or frame is None:
        busy = False
        return
    frame = cv2.flip(frame, 1)
    shot = fit_cv(frame, 720, 540)
    collage_frames.append(shot.copy())
    camera_flash()

    if len(collage_frames) < collage_target:
        busy = False
        panel = None
        camera_ui()
        text(500, 92, f"PHOTO {len(collage_frames)} / {collage_target} — CLICK SHUTTER FOR NEXT", 9, DARK, SANS, weight="bold")
    else:
        busy = False
        mode = "REVIEW"
        panel = None
        review_ui()

# ------------------------------------------------------------
# Actions
# ------------------------------------------------------------
def start_collage(n):
    global collage_target, collage_frames, mode, panel, current_filter, current_frame, busy
    collage_target = n
    collage_frames = []
    current_filter = "ORIGINAL"
    current_frame = "NONE"
    panel = None
    busy = False
    mode = "CAMERA"
    camera_ui()
    text(500, 92, f"COLLAGE — PHOTO 1 / {n}", 9, DARK, SANS, weight="bold")


def retake():
    global mode,panel,collage_frames,collage_target,current_filter,current_frame,busy
    mode="CAMERA"
    panel=None
    collage_frames=[]
    collage_target=1
    current_filter="ORIGINAL"
    current_frame="NONE"
    busy=False
    camera_ui()


def save_photo():
    if not collage_frames:
        return
    final = make_collage()
    final = apply_filter(final, current_filter)
    final = vignette(final, .08)
    final = add_frame_cv(final, current_frame)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    path = os.path.join(PHOTO_DIR, f"snapbox_{stamp}.jpg")
    cv2.imwrite(path, final, [cv2.IMWRITE_JPEG_QUALITY,95])
    text(500, 680, "SAVED ✓", 10, DEEP_PINK, SANS, weight="bold")
    root.after(1500, review_ui)

# ------------------------------------------------------------
# Mouse / keyboard
# ------------------------------------------------------------
def click(event):
    global panel,current_filter,current_frame
    x,y=event.x,event.y

    if mode == "CAMERA":
        if panel == "COLLAGE":
            # Five options, 2 columns.
            for i,n in enumerate(COLLAGES):
                col=i%2; row=i//2
                xx=670+col*145; yy=607+row*34
                if xx<=x<=xx+125 and yy<=y<=yy+27:
                    start_collage(n)
                    return
            # Close popup if clicked outside.
            if not (650<=x<=965 and 565<=y<=700):
                panel=None
                camera_ui()
                return

        # Collage button.
        if 365<=x<=485 and 705<=y<=750:
            panel="COLLAGE"
            camera_ui()
            return

        # Shutter.
        if 500<=x<=600 and 690<=y<=795:
            take_photo()
            return

    elif mode == "REVIEW":
        if 160<=x<=310 and 145<=y<=185:
            panel="FILTERS"; review_ui(); return
        if 325<=x<=475 and 145<=y<=185:
            panel="FRAMES"; review_ui(); return
        if 490<=x<=640 and 145<=y<=185:
            retake(); return
        if 655<=x<=805 and 145<=y<=185:
            save_photo(); return

        if panel == "FILTERS":
            for i,item in enumerate(FILTERS):
                col=i%4; row=i//4
                xx=160+col*165; yy=205+row*38
                if xx<=x<=xx+150 and yy<=y<=yy+30:
                    current_filter=item; review_ui(); return
        elif panel == "FRAMES":
            for i,item in enumerate(FRAMES):
                col=i%4; row=i//4
                xx=160+col*165; yy=205+row*38
                if xx<=x<=xx+150 and yy<=y<=yy+30:
                    current_frame=item; review_ui(); return

canvas.bind("<Button-1>", click)
root.bind("<space>", take_photo)
root.bind("<Escape>", lambda e: retake() if mode=="REVIEW" else None)


def camera_loop():
    global cap
    if mode == "CAMERA" and not busy:
        if not cap.isOpened():
            try:
                cap.release()
            except Exception:
                pass
            cap = open_camera()

        ret, frame = cap.read()
        if ret and frame is not None:
            frame = cv2.flip(frame, 1)
            show_camera_frame(frame)
    root.after(30, camera_loop)


def close():
    try:
        cap.release()
    except Exception:
        pass
    root.destroy()

root.protocol("WM_DELETE_WINDOW", close)
load_background()
camera_ui()
root.after(30, camera_loop)
root.mainloop()
